//! Cross-language contract checks (Phase 2.1).
//!
//! 1. Golden file. The Engine's real message builder is called with fixed inputs and its
//!    output must equal, byte for byte, a committed file under
//!    `courier-contracts/fixtures/v1/produced/`. The Python contract tests validate every file
//!    in that directory against the shared JSON Schemas. A Rust change that alters the message
//!    fails here until the file is regenerated; a regenerated file that breaks the schema, or
//!    a schema change the Rust output no longer satisfies, fails in the Python tests.
//!    Regeneration is an explicit developer action (`make update-contract-fixtures`) and is
//!    refused when the `CI` environment variable is set.
//!
//! 2. Enum parity. The same list of values must exist in the Rust enums, in the PostgreSQL
//!    enums and, where a value crosses the message bus, in the JSON Schemas.

use std::{collections::BTreeSet, fs, path::PathBuf};

use chrono::{DateTime, Duration, TimeZone, Utc};
use courier_engine::{
    db::{self, providers::DispatchTarget},
    domain::{ErrorClass, ExecutionStatus, JobOutcome, JobTrigger, ShipmentStatus, TrackingMethod},
    services::dispatch,
};
use serde::Serialize;
use serde_json::Value;
use sqlx::PgPool;
use uuid::Uuid;

const MIGRATOR: &sqlx::migrate::Migrator = &db::MIGRATOR;
const UPDATE_VAR: &str = "UPDATE_CONTRACT_FIXTURES";

fn contracts_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../courier-contracts")
}

// ----------------------------------------------------------------------------- golden file

fn fixed_uuid(last: u8) -> Uuid {
    Uuid::parse_str(&format!("019355a0-0000-7000-8000-0000000000{last:02x}")).unwrap()
}

/// The message the Engine would send for the seeded dummy provider, with every input fixed.
fn golden_job_track() -> String {
    let dispatched_at: DateTime<Utc> =
        Utc.with_ymd_and_hms(2026, 11, 24, 10, 0, 0).unwrap() + Duration::microseconds(123_456);
    let target = DispatchTarget {
        provider_id: fixed_uuid(1),
        provider_code: "dummy".to_string(),
        adapter_id: fixed_uuid(2),
        adapter_key: "dummy".to_string(),
        timeout_ms: 10_000,
        queue_wait_max_ms: 900_000,
        max_attempts: 3,
        tracking_method: TrackingMethod::Api,
        scraping_authorized: false,
        requires_credential: false,
        min_dispatch_interval_ms: 0,
        credential_id: None,
    };
    let message = dispatch::job_track_message(
        fixed_uuid(0x10),
        &target,
        fixed_uuid(0x20),
        1,
        "DUMMY-OK-1",
        fixed_uuid(0x30),
        dispatched_at,
        dispatched_at + Duration::milliseconds(i64::from(target.queue_wait_max_ms)),
    );
    let mut text = serde_json::to_string_pretty(&message).unwrap();
    text.push('\n');
    text
}

#[test]
fn the_engines_job_track_message_matches_the_committed_fixture() {
    let path = contracts_dir().join("fixtures/v1/produced/job.track.engine.json");
    let produced = golden_job_track();

    if std::env::var_os(UPDATE_VAR).is_some() {
        assert!(
            std::env::var_os("CI").is_none(),
            "{UPDATE_VAR} is set in CI. Fixtures are regenerated by a developer and committed; \
             CI only compares."
        );
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(&path, &produced).unwrap();
        eprintln!("wrote {}", path.display());
        return;
    }

    let committed = fs::read_to_string(&path).unwrap_or_else(|e| {
        panic!(
            "cannot read {} ({e}). Run `make update-contract-fixtures` and commit the file.",
            path.display()
        )
    });
    assert_eq!(
        produced, committed,
        "\nThe Engine's job.track message no longer matches the committed fixture.\n\
         If the change is intended: run `make update-contract-fixtures`, run `make test-contracts` \
         (Python validates the new file against the JSON Schema), review the diff and commit it.\n"
    );
}

// ----------------------------------------------------------------------------- enum parity

/// The names Rust puts on the wire (serde) for a list of variants.
fn wire_names<T: Serialize>(variants: &[T]) -> Vec<String> {
    variants
        .iter()
        .map(|v| match serde_json::to_value(v).unwrap() {
            Value::String(name) => name,
            other => panic!("enum variant serialized as {other}"),
        })
        .collect()
}

fn schema_enum(definition: &str) -> Vec<String> {
    let path = contracts_dir().join("schemas/v1/common.schema.json");
    let schema: Value = serde_json::from_str(&fs::read_to_string(path).unwrap()).unwrap();
    schema["$defs"][definition]["enum"]
        .as_array()
        .unwrap_or_else(|| panic!("common.schema.json has no enum $defs/{definition}"))
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect()
}

async fn postgres_enum(pool: &PgPool, type_name: &str) -> Vec<String> {
    sqlx::query_scalar::<_, String>(
        "SELECT e.enumlabel::text FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid
         WHERE t.typname = $1 ORDER BY e.enumsortorder",
    )
    .bind(type_name)
    .fetch_all(pool)
    .await
    .unwrap()
}

#[sqlx::test(migrator = "MIGRATOR")]
async fn rust_enums_match_the_postgres_enums(pool: PgPool) {
    assert_eq!(
        wire_names(&ExecutionStatus::ALL),
        postgres_enum(&pool, "execution_status").await
    );
    assert_eq!(
        wire_names(&ShipmentStatus::ALL),
        postgres_enum(&pool, "shipment_status").await
    );
    assert_eq!(
        wire_names(&JobOutcome::ALL),
        postgres_enum(&pool, "job_outcome").await
    );
    assert_eq!(
        wire_names(&ErrorClass::ALL),
        postgres_enum(&pool, "error_class").await
    );
    assert_eq!(
        wire_names(&JobTrigger::ALL),
        postgres_enum(&pool, "job_trigger").await
    );
    assert_eq!(
        wire_names(&TrackingMethod::ALL),
        postgres_enum(&pool, "tracking_method").await
    );
}

/// sqlx and serde are configured separately on each enum; this proves every variant survives
/// a real round trip through PostgreSQL under the name serde uses.
#[sqlx::test(migrator = "MIGRATOR")]
async fn every_variant_round_trips_through_postgres(pool: PgPool) {
    for v in ExecutionStatus::ALL {
        let (back, label): (ExecutionStatus, String) =
            sqlx::query_as("SELECT $1::execution_status, $1::execution_status::text")
                .bind(v)
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(back, v);
        assert_eq!(vec![label], wire_names(&[v]));
    }
    for v in ShipmentStatus::ALL {
        let (back, label): (ShipmentStatus, String) =
            sqlx::query_as("SELECT $1::shipment_status, $1::shipment_status::text")
                .bind(v)
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(back, v);
        assert_eq!(vec![label], wire_names(&[v]));
    }
    for v in ErrorClass::ALL {
        let (back, label): (ErrorClass, String) =
            sqlx::query_as("SELECT $1::error_class, $1::error_class::text")
                .bind(v)
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(back, v);
        assert_eq!(vec![label], wire_names(&[v]));
    }
    for v in JobOutcome::ALL {
        let (back, label): (JobOutcome, String) =
            sqlx::query_as("SELECT $1::job_outcome, $1::job_outcome::text")
                .bind(v)
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(back, v);
        assert_eq!(vec![label], wire_names(&[v]));
    }
}

#[test]
fn rust_enums_match_the_json_schema_enums() {
    assert_eq!(wire_names(&JobOutcome::ALL), schema_enum("outcome"));

    // Workers may report every error class except the three only the Engine assigns.
    let worker_classes: Vec<ErrorClass> = ErrorClass::ALL
        .into_iter()
        .filter(|c| !c.is_engine_assigned())
        .collect();
    assert_eq!(wire_names(&worker_classes), schema_enum("workerErrorClass"));
}

// ----------------------------------------------------------------------------- "active job" definition

/// Every single-quoted token in a piece of SQL.
fn quoted(sql: &str) -> BTreeSet<String> {
    sql.split('\'')
        .skip(1)
        .step_by(2)
        .map(str::to_string)
        .collect()
}

/// "Which job statuses are still running" is written in Rust (`is_terminal`), in one Rust SQL
/// constant, and — unavoidably, because migrations are immutable SQL — in the unique index,
/// a CHECK constraint and a trigger. This test fails if any of them disagrees.
#[sqlx::test(migrator = "MIGRATOR")]
async fn the_active_job_status_list_is_the_same_everywhere(pool: PgPool) {
    let active: BTreeSet<String> = wire_names(
        &ExecutionStatus::ALL
            .into_iter()
            .filter(|s| !s.is_terminal())
            .collect::<Vec<_>>(),
    )
    .into_iter()
    .collect();
    let terminal: BTreeSet<String> = wire_names(
        &ExecutionStatus::ALL
            .into_iter()
            .filter(|s| s.is_terminal())
            .collect::<Vec<_>>(),
    )
    .into_iter()
    .collect();
    assert_eq!(active.len() + terminal.len(), ExecutionStatus::ALL.len());

    assert_eq!(
        quoted(db::ACTIVE_JOB_STATUSES_SQL),
        active,
        "Rust SQL constant"
    );

    let index: String = sqlx::query_scalar(
        "SELECT indexdef FROM pg_indexes WHERE indexname = 'ux_tracking_jobs_one_active'",
    )
    .fetch_one(&pool)
    .await
    .unwrap();
    let predicate = index.split(" WHERE ").nth(1).expect("a partial index");
    assert_eq!(quoted(predicate), active, "unique index predicate");

    let check: String = sqlx::query_scalar(
        "SELECT pg_get_constraintdef(oid) FROM pg_constraint
         WHERE conname = 'ck_jobs_completed_at_matches_terminal'",
    )
    .fetch_one(&pool)
    .await
    .unwrap();
    assert_eq!(quoted(&check), terminal, "CHECK constraint");

    let trigger: String = sqlx::query_scalar(
        "SELECT prosrc FROM pg_proc WHERE proname = 'forbid_archiving_shipment_with_active_job'",
    )
    .fetch_one(&pool)
    .await
    .unwrap();
    let list = trigger
        .split("j.status IN")
        .nth(1)
        .and_then(|rest| rest.split(')').next())
        .expect("the trigger lists statuses");
    assert_eq!(quoted(list), active, "archive trigger");
}

// ----------------------------------------------------------------------------- shared fixtures

use courier_engine::messaging::contracts::{parse_incoming_event, parse_job_track};

fn fixtures(directory: &str) -> Vec<(String, Vec<u8>)> {
    let mut found: Vec<_> = fs::read_dir(contracts_dir().join("fixtures/v1").join(directory))
        .unwrap()
        .map(|entry| entry.unwrap().path())
        .filter(|path| {
            let name = path.file_name().unwrap().to_string_lossy().into_owned();
            name.ends_with(".json") && !name.starts_with('_')
        })
        .map(|path| {
            (
                path.file_name().unwrap().to_string_lossy().into_owned(),
                fs::read(&path).unwrap(),
            )
        })
        .collect();
    found.sort();
    found
}

/// Runs a fixture through the parser the Engine uses for that message type.
fn parse_fixture(name: &str, body: &[u8]) -> Result<(), String> {
    if name.starts_with("job.track.") {
        parse_job_track(body).map(|_| ()).map_err(|e| e.0)
    } else {
        parse_incoming_event(body).map(|_| ()).map_err(|e| e.0)
    }
}

/// The Rust validation is hand-written, not generated from the JSON Schemas. These two tests
/// are what keeps it honest: it must agree with the schemas on every shared fixture — the
/// same files the Python validator is tested against.
#[test]
fn every_valid_fixture_is_accepted_by_the_engine() {
    let valid = fixtures("valid");
    assert!(valid.len() >= 14);
    for (name, body) in valid.iter().chain(fixtures("produced").iter()) {
        if let Err(reason) = parse_fixture(name, body) {
            panic!("{name} was rejected: {reason}");
        }
    }
}

#[test]
fn every_invalid_fixture_is_rejected_by_the_engine() {
    let invalid = fixtures("invalid");
    assert!(invalid.len() >= 24);
    for (name, body) in &invalid {
        assert!(
            parse_fixture(name, body).is_err(),
            "{name} was accepted but the schema rejects it"
        );
    }
    // Every fixture listed in the expectations file was exercised (none silently skipped).
    let expectations: Value = serde_json::from_slice(
        &fs::read(contracts_dir().join("fixtures/v1/invalid/_expectations.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(expectations.as_object().unwrap().len(), invalid.len());
}

/// A fixture routed to the wrong parser must not slip through on its `type`.
#[test]
fn a_message_of_another_type_is_rejected() {
    for (name, body) in fixtures("valid") {
        if name.starts_with("job.track.") {
            assert!(
                parse_incoming_event(&body).is_err(),
                "{name} accepted as a worker event"
            );
        } else {
            assert!(
                parse_job_track(&body).is_err(),
                "{name} accepted as job.track"
            );
        }
    }
}
